#include <Adafruit_ILI9341.h>
#include <Adafruit_STMPE610.h>
#include <Adafruit_GFX.h>

#define TFT_CS 10
#define TFT_DC 9
#define STMPE_CS 8

Adafruit_ILI9341 tft = Adafruit_ILI9341(TFT_CS, TFT_DC);
Adafruit_STMPE610 touch = Adafruit_STMPE610(STMPE_CS);

const int doubleTapTimeout = 300; // milliseconds
const int doubleTapThreshold = 10; // pixels

int lastTapX = 0;
int lastTapY = 0;
unsigned long lastTapTime = 0;

void setup() {
  Serial.begin(9600);
  tft.begin();
  touch.begin();
  tft.setRotation(1);
  tft.fillScreen(ILI9341_BLACK);
}

void loop() {
  if (touch.touched()) {
    int16_t x, y;
    touch.getTouch(&x, &y);
    if (millis() - lastTapTime < doubleTapTimeout) {
      int deltaX = abs(x - lastTapX);
      int deltaY = abs(y - lastTapY);
      if (deltaX < doubleTapThreshold && deltaY < doubleTapThreshold) {
        Serial.println("Double tap detected!");
        // Do something here when a double tap is detected
      }
    } else {
      lastTapX = x;
      lastTapY = y;
      lastTapTime = millis();
    }
  }
}
```
