impl Cube {
    fn get_neighbors(&self) -> Vec<Cube> {
        let mut neighbors = Vec::new();

        for x in -1..=1 {
            for y in -1..=1 {
                for z in -1..=1 {
                    if x == 0 && y == 0 && z == 0 {
                        // Skip the center position
                        continue;
                    }
                    if x != 0 && y != 0 && z != 0 {
                        // Skip diagonal neighbors
                        continue;
                    }
                    neighbors.push(Cube {
                        x: self.x + x,
                        y: self.y + y,
                        z: self.z + z,
                    });
                }
            }
        }

        neighbors
    }
}
